-- Service data for paying (D127 §Records; ticket #104; design
-- docs/deliverables/2026-10-25-guest-payment-design.md §7): payments, their lines and steps, the
-- venue's payment account, and the provider's notices. Generated by drizzle-kit, then edited by
-- hand: row-level security and the updated_at triggers are appended. Privileges come from
-- src/table-access.ts (`payment_steps` is append-only; `provider_notices` is platform-level, with
-- no tenant, so it has no row-level security). No data.
--
-- `locks_holder_deadline` changes for one scope: a payment owns its payment table until the
-- payment is final and the table reads empty, and no lock runs out meanwhile (D127 3.11). A held
-- `payment_table` row therefore has no deadline, and every other held row keeps one. No code takes
-- a payment-table lease yet, so no row breaks the new check; if one did, the migration would stop
-- rather than release it.
CREATE TABLE "restro"."payment_accounts" (
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"provider_kind" text NOT NULL,
	"account_ref" text,
	"account_name" text,
	"state" text NOT NULL,
	"checks" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"checked_at" timestamp with time zone,
	"connected_at" timestamp with time zone,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payment_accounts_pk" PRIMARY KEY("tenant_id","venue_id"),
	CONSTRAINT "payment_accounts_provider_kind" CHECK ("restro"."payment_accounts"."provider_kind" ~ '^[a-z][a-z0-9-]{0,31}$'),
	CONSTRAINT "payment_accounts_account_ref" CHECK ("restro"."payment_accounts"."account_ref" is null or "restro"."payment_accounts"."account_ref" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$'),
	CONSTRAINT "payment_accounts_account_name" CHECK ("restro"."payment_accounts"."account_name" is null or char_length("restro"."payment_accounts"."account_name") between 1 and 200),
	CONSTRAINT "payment_accounts_state" CHECK ("restro"."payment_accounts"."state" in ('connecting', 'connected', 'lost_access', 'disconnected')),
	CONSTRAINT "payment_accounts_connected_has_account" CHECK ("restro"."payment_accounts"."state" not in ('connected', 'lost_access') or "restro"."payment_accounts"."account_ref" is not null),
	CONSTRAINT "payment_accounts_checks_object" CHECK (jsonb_typeof("restro"."payment_accounts"."checks") = 'object'),
	CONSTRAINT "payment_accounts_source" CHECK ("restro"."payment_accounts"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "payment_accounts_actor" CHECK ("restro"."payment_accounts"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "payment_accounts_job_id" CHECK ("restro"."payment_accounts"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
--> statement-breakpoint
CREATE TABLE "restro"."payment_lines" (
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"payment_id" text NOT NULL,
	"position" integer NOT NULL,
	"pos_line_ref" text,
	"quantity" numeric(21, 6) NOT NULL,
	"pos_amount_minor" bigint NOT NULL,
	"display_name" text NOT NULL,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payment_lines_pk" PRIMARY KEY("tenant_id","payment_id","position"),
	CONSTRAINT "payment_lines_position" CHECK ("restro"."payment_lines"."position" >= 1),
	CONSTRAINT "payment_lines_quantity" CHECK ("restro"."payment_lines"."quantity" > 0),
	CONSTRAINT "payment_lines_pos_line_ref" CHECK ("restro"."payment_lines"."pos_line_ref" is null or char_length("restro"."payment_lines"."pos_line_ref") between 1 and 255),
	CONSTRAINT "payment_lines_display_name" CHECK (char_length("restro"."payment_lines"."display_name") between 1 and 200),
	CONSTRAINT "payment_lines_source" CHECK ("restro"."payment_lines"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "payment_lines_actor" CHECK ("restro"."payment_lines"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "payment_lines_job_id" CHECK ("restro"."payment_lines"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
--> statement-breakpoint
CREATE TABLE "restro"."payment_steps" (
	"seq" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "restro"."payment_steps_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"payment_id" text NOT NULL,
	"step" text NOT NULL,
	"outcome" text NOT NULL,
	"answer" text,
	"idempotency_key" text,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	CONSTRAINT "payment_steps_step" CHECK ("restro"."payment_steps"."step" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "payment_steps_outcome" CHECK ("restro"."payment_steps"."outcome" in ('attempting', 'done', 'refused', 'unknown')),
	CONSTRAINT "payment_steps_answer" CHECK ("restro"."payment_steps"."answer" is null or char_length("restro"."payment_steps"."answer") between 1 and 500),
	CONSTRAINT "payment_steps_idempotency_key" CHECK ("restro"."payment_steps"."idempotency_key" is null or "restro"."payment_steps"."idempotency_key" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$'),
	CONSTRAINT "payment_steps_source" CHECK ("restro"."payment_steps"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "payment_steps_actor" CHECK ("restro"."payment_steps"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "payment_steps_job_id" CHECK ("restro"."payment_steps"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
