CREATE TABLE "restro"."payments" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"table_id" text NOT NULL,
	"sitting_id" text NOT NULL,
	"bar_id" text,
	"sent_order_id" text,
	"service_date" date NOT NULL,
	"kind" text NOT NULL,
	"state" text NOT NULL,
	"reason" text,
	"handle_hash" text NOT NULL,
	"action_id" text,
	"amount_minor" bigint,
	"tip_minor" bigint DEFAULT 0 NOT NULL,
	"captured_minor" bigint,
	"currency" text NOT NULL,
	"confirm_by" timestamp with time zone,
	"session_ends_at" timestamp with time zone,
	"queue_ends_at" timestamp with time zone,
	"payment_table_id" text,
	"provider_kind" text NOT NULL,
	"provider_payment_ref" text,
	"capture_before" timestamp with time zone,
	"receipt_number" text,
	"fiscal_memory_number" text,
	"three_ds_result" text,
	"authorisation_code" text,
	"settled_at" timestamp with time zone,
	"retain_until" timestamp with time zone,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payments_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "payments_tenant_id_action_id_unique" UNIQUE("tenant_id","action_id"),
	CONSTRAINT "payments_handle_hash_unique" UNIQUE("handle_hash"),
	CONSTRAINT "payments_id_format" CHECK ("restro"."payments"."id" ~ '^py_[0-9A-Za-z]+$'),
	CONSTRAINT "payments_kind" CHECK ("restro"."payments"."kind" in ('on_bill', 'pay_first')),
	CONSTRAINT "payments_state" CHECK ("restro"."payments"."state" in ('requested', 'priced', 'awaiting_guest', 'held', 'queued', 'isolated', 'entered', 'checked', 'closed', 'cancelling', 'captured', 'released', 'unconfirmed', 'stranded', 'capture_failed')),
	CONSTRAINT "payments_pay_first_sent_order" CHECK (("restro"."payments"."kind" = 'pay_first') = ("restro"."payments"."sent_order_id" is not null)),
	CONSTRAINT "payments_reason" CHECK ("restro"."payments"."reason" is null or "restro"."payments"."reason" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "payments_handle_hash" CHECK ("restro"."payments"."handle_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "payments_action_id" CHECK ("restro"."payments"."action_id" is null or "restro"."payments"."action_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "payments_amounts" CHECK ("restro"."payments"."tip_minor" >= 0 and ("restro"."payments"."amount_minor" is null or "restro"."payments"."amount_minor" >= "restro"."payments"."tip_minor")),
	CONSTRAINT "payments_captured_minor" CHECK ("restro"."payments"."captured_minor" is null or ("restro"."payments"."amount_minor" is not null and "restro"."payments"."captured_minor" between 0 and "restro"."payments"."amount_minor")),
	CONSTRAINT "payments_currency" CHECK ("restro"."payments"."currency" ~ '^[A-Z]{3}$'),
	CONSTRAINT "payments_provider_kind" CHECK ("restro"."payments"."provider_kind" ~ '^[a-z][a-z0-9-]{0,31}$'),
	CONSTRAINT "payments_provider_payment_ref" CHECK ("restro"."payments"."provider_payment_ref" is null or "restro"."payments"."provider_payment_ref" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$'),
	CONSTRAINT "payments_fiscal_numbers" CHECK (("restro"."payments"."receipt_number" is null or char_length("restro"."payments"."receipt_number") between 1 and 64) and ("restro"."payments"."fiscal_memory_number" is null or char_length("restro"."payments"."fiscal_memory_number") between 1 and 64)),
	CONSTRAINT "payments_evidence" CHECK (("restro"."payments"."three_ds_result" is null or "restro"."payments"."three_ds_result" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$') and ("restro"."payments"."authorisation_code" is null or char_length("restro"."payments"."authorisation_code") between 1 and 64)),
	CONSTRAINT "payments_settled" CHECK (("restro"."payments"."settled_at" is not null) = ("restro"."payments"."state" in ('captured', 'released', 'unconfirmed', 'stranded', 'capture_failed'))),
	CONSTRAINT "payments_source" CHECK ("restro"."payments"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "payments_actor" CHECK ("restro"."payments"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "payments_job_id" CHECK ("restro"."payments"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
