CREATE TABLE "restro"."provider_notices" (
	"seq" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "restro"."provider_notices_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"provider_kind" text NOT NULL,
	"event_id" text NOT NULL,
	"live" boolean NOT NULL,
	"account_ref" text,
	"type" text NOT NULL,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"handled_at" timestamp with time zone,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	CONSTRAINT "provider_notices_event_unique" UNIQUE("provider_kind","event_id"),
	CONSTRAINT "provider_notices_provider_kind" CHECK ("restro"."provider_notices"."provider_kind" ~ '^[a-z][a-z0-9-]{0,31}$'),
	CONSTRAINT "provider_notices_event_id" CHECK ("restro"."provider_notices"."event_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$'),
	CONSTRAINT "provider_notices_account_ref" CHECK ("restro"."provider_notices"."account_ref" is null or "restro"."provider_notices"."account_ref" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}$'),
	CONSTRAINT "provider_notices_type" CHECK ("restro"."provider_notices"."type" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "provider_notices_handled_after_received" CHECK ("restro"."provider_notices"."handled_at" is null or "restro"."provider_notices"."handled_at" >= "restro"."provider_notices"."received_at"),
	CONSTRAINT "provider_notices_source" CHECK ("restro"."provider_notices"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "provider_notices_actor" CHECK ("restro"."provider_notices"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "provider_notices_job_id" CHECK ("restro"."provider_notices"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
